
CREATE TABLE IF NOT EXISTS `__sires_clients` (
  `SID` int(1) NOT NULL AUTO_INCREMENT COMMENT 'Identificador del registro.',
  `SClientID` int(1) NOT NULL DEFAULT '0' COMMENT 'Identificador del paciente (clients)',
  `SClientFieldID` int(1) DEFAULT '0' COMMENT 'Identificador del campo según el SIRES (__sires_x_config_field.FieldID)',
  `SClientFieldValue` varchar(100) COLLATE latin1_spanish_ci DEFAULT '' COMMENT 'Valor del campo según el SIRES (__sires_x_config_field.FieldJsonValues)',
  `SClientDateTime` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha y hora en que el registro es generado.',
  PRIMARY KEY (`SID`),
  KEY `SClientFieldID` (`SClientFieldID`),
  KEY `SClientID` (`SClientID`)
) ENGINE=InnoDB AUTO_INCREMENT=481 DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci COMMENT='Registros de  clientes con consultas a intercambiar con el SIRES (méxico)';

CREATE TABLE IF NOT EXISTS `__sires_delete_registry` (
  `SRegistryID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Identificador del registro.',
  `SRegistryDiarySGID` int(11) NOT NULL DEFAULT '0' COMMENT 'Identificador de la consulta del SIRES eliminada.',
  `SRegistryTypeDiary` int(11) NOT NULL DEFAULT '0' COMMENT 'Tipo de consulta.',
  `SRegistryUserID` int(11) NOT NULL DEFAULT '0' COMMENT 'Identificador del usuario que realiza la acción.',
  `SRegistryHeadData` text COLLATE latin1_spanish_ci NOT NULL COMMENT 'Cabecera de las variables de la consulta.',
  `SRegistryData` text COLLATE latin1_spanish_ci NOT NULL COMMENT 'Valores de la consulta eliminada.',
  `SRegistryClinicID` int(11) NOT NULL DEFAULT '0' COMMENT 'Clínica desde la que se realiza la acción.',
  `SRegistryDateTime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Fecha y hora en la que se produce la acción',
  PRIMARY KEY (`SRegistryID`),
  KEY `SRegistryUserID` (`SRegistryUserID`),
  KEY `SRegistryClinicID` (`SRegistryClinicID`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci COMMENT='Registro de cosultas eliminadas';

CREATE TABLE IF NOT EXISTS `__sires_diary_det` (
  `SDiaryID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Identificador del registro de la variable.',
  `SDiaryGID` int(11) DEFAULT '0' COMMENT 'Identificador de la consulta.',
  `SDiaryFieldID` int(11) DEFAULT '0' COMMENT 'Identificador de la variable.',
  `SDiaryFieldValue` varchar(100) COLLATE latin1_spanish_ci DEFAULT '' COMMENT 'Valor de la variable.',
  `SDiaryDateTime` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha y hora del registro del valor de la variable.',
  PRIMARY KEY (`SDiaryID`),
  KEY `SDiaryGID` (`SDiaryGID`),
  KEY `SDiaryFielID` (`SDiaryFieldID`)
) ENGINE=InnoDB AUTO_INCREMENT=6891 DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci COMMENT='Variables por consulta a registrar en el SIRES (México).';

CREATE TABLE IF NOT EXISTS `__sires_diary_gen` (
  `SDiaryGID` int(1) NOT NULL AUTO_INCREMENT COMMENT 'Identificador de la consulta para el SIRES',
  `DiaryGID` int(1) DEFAULT '0' COMMENT 'Identificador de la cita en flowww (deshabiditado en V1)',
  `SClinicID` int(1) DEFAULT '0' COMMENT 'Clínica en la que se realiza la consulta.',
  `SDiaryGClientID` int(1) NOT NULL DEFAULT '0' COMMENT 'Identificador del cliente (clients.ClientID)',
  `SDiaryGUserID` int(1) NOT NULL DEFAULT '0' COMMENT 'Identificador del usuario que crea el registro de la consulta.',
  `SDiaryGType` int(1) NOT NULL DEFAULT '0' COMMENT 'Tipo consulta. 0 - externa, 1- Bucal',
  `SDiaryGDate` date DEFAULT NULL COMMENT 'Fecha de la consulta',
  `SDiaryGServiceID` int(11) NOT NULL DEFAULT '0' COMMENT 'Servicio que se brinda en la consulta.',
  `SDiaryGDateTime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha y hora del registro de la consulta.',
  `SDiaryGIdExport` int(1) DEFAULT '0' COMMENT 'Determina si la cita ya está exportada el SIRES.(-1)',
  `SDiaryGBodyExport` text COLLATE latin1_spanish_ci COMMENT 'Cadena de valores exportado',
  PRIMARY KEY (`SDiaryGID`)
) ENGINE=InnoDB AUTO_INCREMENT=91 DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci COMMENT='Consultas que se deben registar en el SIRES (México)';

CREATE TABLE IF NOT EXISTS `__sires_diary_gen_export` (
  `SExportID` int(1) NOT NULL AUTO_INCREMENT COMMENT 'Identificador de la exportación.',
  `SExportIDLastID` int(1) NOT NULL DEFAULT '0' COMMENT 'Determina el ID de la ultima expostación. Considerar que cada exportación es incremental.',
  `SExportUserID` int(1) NOT NULL DEFAULT '0' COMMENT 'Usuario que realizó la exportación.',
  `SExportHead` text COLLATE latin1_spanish_ci COMMENT 'Cabecera de los campos exportados.',
  `SExportDateTime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Fecha de realizada la exportación.',
  `SExportDateConfirmed` timestamp NULL DEFAULT NULL COMMENT 'Fecha en la que se confirmado la importación el SIRES.',
  `SExportUserIDConfirm` int(1) DEFAULT NULL COMMENT 'Usuario que confirma la importación al SIRES',
  `SExportDateStart` date DEFAULT NULL COMMENT 'Periodo de exportación. Fecha inicial.',
  `SExportDateEnd` date DEFAULT NULL COMMENT 'Periodo de exportación. Fecha final.',
  `SExportTypeDiary` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'Determina el tipo de guía a exportar 1-Bucal, 2-Consulta externa',
  `SExportClinicID` tinyint(4) NOT NULL DEFAULT '0' COMMENT 'Determina la clínicaa ala que realciona la exportación.',
  `SExportNameFile` varchar(50) COLLATE latin1_spanish_ci DEFAULT NULL COMMENT 'Determina el nombre del archivo guardado en el servidor.',
  PRIMARY KEY (`SExportID`),
  KEY `SExportIDLastID` (`SExportIDLastID`),
  KEY `SExportUserID` (`SExportUserID`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci COMMENT='Rsumen de las exportaciones realizadas.';

