	(130, 'asesoriaNutricional ', 'Identifica las intervenciones realizadas por los Gerontólogos relacionados a asesoría nutricional', 'INT', 'SELECT', '{\r\n  "values": [\r\n    {\r\n      "id": 1,\r\n      "name": "PREVENTIVA"\r\n    },\r\n    {\r\n      "id": 2,\r\n      "name": "TRATAMIENTO"\r\n    }\r\n  ]\r\n}', 0, '', NULL, 'Si el valor de la variable “tipoPersonal” es diferente a “7 – PASANTE DE \r\nNUTRICIÓN”, “8 – NUTRIÓLOGA(O)”, “9 – \r\nHOMEÓPATA”,  “10  –  MÉDICA(O) \r\nTRADICIONAL INDÍGENA”, “11 – TAPS”, “21 – PARTERA(O) TÉCNICA(O)”, “22 – PROMOTOR(A) DE SALUD”, o “29 – ACUPUNTURISTA” y la edad del paciente es mayor o igual a “60 años”, se puede registrar una de las siguientes opciones: \r\n1  – PREVENTIVA \r\n2  – TRATAMIENTO \r\nEn caso contrario o no aplica, se debe registrar el valor “-1”. \r\n', 18, '-1', '2025-07-30 14:42:52', 0, 2, 0, NULL, 7, 2),
	(131, 'numeroSobresVSOPromocion', 'Hace referencia al número de sobres Vida Suero Oral en promoción ', 'INT', 'NUMERIC', NULL, 0, '', NULL, 'Si el valor de la variable “tipoPersonal” es diferente de “15 – PASANTE DE \r\nPSICOLOGÍA” y “16 – PSICÓLOGA(O)”, se puede registrar un valor de entre “0” hasta “9”. \r\nEn caso contrario o no aplica, se debe registrar el valor “0”. \r\n', 6, '0', '2025-07-30 14:42:59', -1, 2, 0, NULL, 1, 2);CREATE TABLE IF NOT EXISTS `__sires_x_config_field_section` (
  `FieldSectionID` int(11) NOT NULL AUTO_INCREMENT COMMENT 'Identificador de la sección.',
  `FieldSectionDesc` varchar(250) COLLATE latin1_spanish_ci NOT NULL DEFAULT '' COMMENT 'Nombre de la Sección',
  `FieldSectionDisabled` smallint(6) NOT NULL DEFAULT '0' COMMENT 'Determina si la sección se encuenta activa.',
  `FieldSectionView` smallint(6) NOT NULL DEFAULT '1' COMMENT 'Determina los tipos de formularios e los que debe mostrarse la sección. (0-Cualquiera,1-Bucal,2-Consulta Externa)',
  `FieldSectionCheckFn` text COLLATE latin1_spanish_ci COMMENT 'Función de validación de los valores minimos de la sección (JaveScript)',
  `FieldSectionCheckFnDesc` text COLLATE latin1_spanish_ci COMMENT 'Descripción de la función de validación de la sección.',
  `FieldSectionTypeData` smallint(6) DEFAULT '0' COMMENT 'Determina si correspone a la sección pertenece al cliente, entidad o consulta. 1-Cliente,2-Entidad,3-Personal,0-Consulta',
  `FieldSectionOrder` smallint(6) DEFAULT '0' COMMENT 'Determina el orden de aparición de las secciones.',
  `FieldLastUpdate` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Determina la fecha y hora de última modificación del registro.',
  PRIMARY KEY (`FieldSectionID`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci COMMENT='Determina las secciones a mostrar el formulario del SIRES (México)';INSERT INTO `__sires_x_config_field_section` (`FieldSectionID`, `FieldSectionDesc`, `FieldSectionDisabled`, `FieldSectionView`, `FieldSectionCheckFn`, `FieldSectionCheckFnDesc`, `FieldSectionTypeData`, `FieldSectionOrder`, `FieldLastUpdate`) VALUES
